export default function Contours({ name = 'islands' }: { name?: PatternName }) {
  return (
    <svg
      className={`contours contours--${name}`}
      viewBox="0 0 1440 560"
      preserveAspectRatio="xMidYMid slice"
      aria-hidden="true"
      focusable="false"
    >
      <g fill="none" stroke="currentColor" strokeWidth="1">
        {patterns[name].map((d, i) => (
          <path key={i} d={d} />
        ))}
      </g>
    </svg>
  );
}
